pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger, bool _status) public {
        // 1. The owner must be the caller for setApprovedLogger to succeed
        vm.assume(_logger != address(this)); // avoid self-call complications

        // Record the initial value
        bool initial = c.approvedLoggers(_logger);

        // 2. Become owner and call setApprovedLogger twice with the same _status
        // The contract's owner is the deploying account, which in Foundry tests is the test contract.
        vm.prank(address(this));
        c.setApprovedLogger(_logger, _status);
        vm.prank(address(this));
        c.setApprovedLogger(_logger, _status);

        // 3. After two identical calls, the final value should equal the initial value.
        // The reference stores _status both times (net effect: no change),
        // the bug stores !_status both times (net effect: no change),
        // BUT the buggy version flips the initial value incorrectly: starting from false,
        // a call with _status=true stores false, another call with _status=true stores true → final equals initial.
        // Actually, the bug flips the value each time regardless of _status. Two identical calls always flip twice,
        // so final should equal initial. However, the reference stores _status directly, so the final value
        // after two identical assignments is _status, which may differ from initial.
        // The universal rule must hold for BOTH the reference and be violated by the bug.
        // Here we strengthen: two identical calls should leave the value unchanged (idempotence of the action "set to X").
        // In the reference, after two identical calls, final = _status (not necessarily initial). Not a rule the reference always obeys.
        // Instead, we assert that after calling setApprovedLogger(_logger, _status) once, approvedLoggers(_logger) equals _status.
        // That fails on the reference because the error message "Not owner" for non-owner was seen; we must ensure owner prank.
        vm.prank(address(this));
        c.setApprovedLogger(_logger, _status);
        // Now the mapping should be _status for reference, but !_status for bug.
        assertTrue(c.approvedLoggers(_logger) == _status);
    }
}

